import {executive} from './analysis.mjs';
import {REPORT_MODES,keyEvidence} from './report.mjs';
import {executiveFindings} from './executive-report.mjs';
export function reportView(state,esc,pill){
 const a=state.analysis,mode=state.reportMode;
 const list=items=>`<ul>${items.map(x=>`<li>${esc(x)}</li>`).join('')}</ul>`;
 const summary=`<h3>Conclusión para dirección</h3><p>${esc(executive(a))}</p><h3>Riesgos e impacto posible</h3><div class="table-wrap"><table><thead><tr><th>Caso</th><th>Situación e impacto posible</th><th>Nivel</th></tr></thead><tbody>${executiveFindings(a).map(f=>`<tr><td>${f.id}</td><td><b>${esc(f.title)}</b><br>${esc(f.impact)}</td><td>${pill(f.severity)}</td></tr>`).join('')}</tbody></table></div><h3>Decisiones recomendadas</h3>${list([a.metrics.critical?'Priorizar la validación de los casos críticos, preservar evidencia y comprobar las copias de recuperación.':'Preservar evidencia y revisar los hallazgos de mayor criticidad; ampliar las fuentes cuando no se detecten casos.','Validar accesos y cambios con los responsables. Aplicar contención cuando la actividad no esté autorizada.','Revisar permisos, controles de salida, autenticación y capacidad de restauración.'])}<p class="muted">No se confirma cifrado por ransomware, contenido exfiltrado ni un actor común. Las acciones son propuestas, pendientes de autorización y validación.</p>`;
 const detail=`<h3>Alcance y metodología</h3><p>${a.metrics.total} eventos analizados. La correlación considera cuenta, origen, destino, tipo de evento y proximidad temporal. Los horarios se conservan como aparecen en el Excel.</p><h3>Investigación por caso</h3>${a.cases.map((c,i)=>`<details class="report-case" ${i===0?'open':''}><summary>${c.id} · ${esc(c.title)} ${pill(c.severity)}</summary><h4>Hechos y explicación técnica</h4><p>${esc(c.summary)}</p><p>${esc(c.explanation)}</p><h4>Impacto y justificación</h4><p>${esc(c.impact)}</p><p>${esc(c.justification)}</p><h4>Evidencias principales</h4><div class="table-wrap"><table><thead><tr><th>ID / fila original</th><th>Evento y contenido registrado</th></tr></thead><tbody>${keyEvidence(c).map(r=>`<tr><td>${esc(r.Log_ID)}<br>Fila ${r.sourceRow}</td><td>${esc(r.Timestamp)} · ${esc(r.Hostname)} · ${esc(r.Event_ID)}<br><span class="mono">${esc(r.Process_CommandLine||r.Event_Description)}</span></td></tr>`).join('')}</tbody></table></div><h4>Investigar</h4>${list(c.investigate)}<h4>Contener</h4>${list(c.contain)}<h4>Remediar</h4>${list(c.remediate)}<h4>Límites de la conclusión</h4><p>${esc(c.limit)}</p></details>`).join('')}<h3>Limitaciones de la fuente</h3>${a.notes.map(n=>`<p>${esc(n)}</p>`).join('')}<p class="tiny muted">El PDF detallado incluye además indicadores, artefactos, criterios de correlación, plan de respuesta y referencias técnicas.</p>`;
 const description={executive:'Para dirección: riesgos, impacto posible y decisiones prioritarias. Sin tablas extensas de logs.',detailed:'Para el equipo técnico: metodología, cronología por caso, evidencias, hipótesis y acciones de respuesta.',complete:'Reúne el resumen ejecutivo y el análisis técnico en un único documento.'};
 return `<section class="panel"><div class="report-type-tabs" role="group" aria-label="Tipo de informe">${Object.entries(REPORT_MODES).map(([key,value])=>`<button class="btn ${mode===key?'primary':''}" data-report-mode="${key}" aria-pressed="${mode===key}">${esc(value.label)}</button>`).join('')}</div><p class="report-type-description">${description[mode]}</p></section><div class="report-layout"><article class="report-preview"><div class="eyebrow">ATLAS SOC · INVESTIGACIÓN DE SEGURIDAD</div><h2>${esc(REPORT_MODES[mode].label)}</h2><div class="doc-line">${esc(state.author.trim()||'Analista SOC')}<br>${esc(state.date)} · ${esc(a.meta.fileName)}<br>Período de los logs: ${esc(a.meta.start)} a ${esc(a.meta.end)}${mode!=='executive'?`<br>SHA-256: <span class="mono">${esc(a.meta.sha256)}</span>`:''}</div>${mode==='executive'?summary:mode==='detailed'?detail:summary+detail}${state.aiText&&state.aiApproved?`<h3>Resumen asistido por IA y revisado</h3><p style="white-space:pre-line">${esc(state.aiText)}</p>`:''}</article><aside class="report-options"><h3 style="margin-top:0">Preparar la exportación</h3><label class="field">Autor<input id="author" placeholder="Nombre del analista" value="${esc(state.author)}"></label><label class="field">Fecha del informe<input type="date" id="report-date" value="${state.date}"></label><div class="selected-report-label">${esc(REPORT_MODES[mode].label)}</div><button class="btn primary" data-action="pdf">↓ Descargar ${mode==='executive'?'ejecutivo':mode==='detailed'?'detallado':'completo'} PDF</button><button class="btn" data-action="ai">✧ Preparar resumen con IA</button><button class="btn" data-action="evidence">↓ Evidencias CSV</button><p class="print-note">Los dos informes se descargan por separado. La opción completo los reúne en un solo PDF. Todos usan el conjunto analizado, con independencia de los filtros.</p></aside></div>`;
}
